function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 1000) return 'arr needs 1 to 1000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value is an integer from 1 to 1000.';
  return null;
}

