function threeConsecutiveOdds(arr) {
  let streak = 0;

  for (const value of arr) {
    if (value % 2 === 1) {
      streak++;
    } else {
      streak = 0;
    }
    if (streak === 3) {
      return true;
    }
  }
  return false;
}

