function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 8);
  const limit = size === 'large' ? 1000 : 12;
  const oddChance = 0.2 + rand() * 0.6;
  // Sometimes forbid a third odd in a row so that "false" also appears on longer inputs.
  const avoid = rand() < 0.5;
  const arr = [];
  let run = 0;
  for (let i = 0; i < n; i++) {
    let odd = rand() < oddChance;
    if (avoid && run === 2) odd = false;
    const half = Math.floor(rand() * (limit / 2));
    arr.push(odd ? 2 * half + 1 : 2 * half + 2);
    run = odd ? run + 1 : 0;
  }
  return [arr];
}
